<?php
declare(strict_types=1);

function student_shell_activity(?array $activity,?array $student): ?array {return $activity;}
function student_shell_active_area(string $path): string {
    if(str_contains($path,'perfil')||str_contains($path,'senha'))return 'account';
    if(str_contains($path,'caderno')||str_contains($path,'teste')||str_contains($path,'comparar-processos'))return 'notebook';
    if(str_contains($path,'ferramentas')||str_contains($path,'reciprocidade')||str_contains($path,'exposicao')||str_contains($path,'temporizador')||str_contains($path,'calibracao')||str_contains($path,'preparo-solucoes')||str_contains($path,'inventario')||str_contains($path,'preparos'))return 'tools';
    return 'courses';
}
function student_course_context_header(array $enrollment,string $active='overview',string $materialUrl=''): void {
    $cohortUuid=(string)($enrollment['cohort_uuid']??'');$overviewUrl='/aluno/?cohort='.rawurlencode($cohortUuid);$questionsUrl='/aluno/duvidas.php?cohort='.rawurlencode($cohortUuid);$statusLabel=function_exists('student_enrollment_cohort_status_label')?student_enrollment_cohort_status_label((string)($enrollment['cohort_status']??'')):(string)($enrollment['cohort_status']??'');?>
    <header class="student-course-context" aria-label="Contexto do curso"><a class="student-course-context-back" href="/aluno/">← Meus cursos</a><div class="student-course-context-head"><div><p class="student-course-context-kicker"><?=h((string)($enrollment['cohort_title']??''))?></p><h1 class="student-course-context-title"><?=h((string)($enrollment['course_title']??'Curso'))?></h1></div><?php if($statusLabel!==''):?><span class="student-status student-course-context-status"><?=h($statusLabel)?></span><?php endif;?></div><nav class="student-course-context-nav" aria-label="Navegação do curso"><a href="<?=h($overviewUrl)?>"<?=$active==='overview'?' aria-current="page"':''?>>Visão geral</a><?php if($materialUrl!==''):?><a href="<?=h($materialUrl)?>"<?=$active==='material'?' aria-current="page"':''?>>Material</a><?php endif;?><a href="<?=h($questionsUrl)?>"<?=$active==='questions'?' aria-current="page"':''?>>Dúvidas</a></nav></header><?php
}
function student_shell_nav(string $active,string $class): void {?>
<nav class="<?=h($class)?>" aria-label="Área do aluno"><a href="/aluno/"<?=$active==='courses'?' aria-current="page"':''?>><span>01</span>Meus cursos</a><a href="/aluno/caderno.php"<?=$active==='notebook'?' aria-current="page"':''?>><span>02</span>Caderno</a><a href="/aluno/ferramentas.php"<?=$active==='tools'?' aria-current="page"':''?>><span>03</span>Ferramentas</a><a href="/aluno/perfil.php"<?=$active==='account'?' aria-current="page"':''?>><span>04</span>Conta</a></nav><?php
